select #{item.monthPlanApsVersion,jdbcType=VARCHAR},#{item.monthPlanVersion,jdbcType=VARCHAR}, #{item.year,jdbcType=VARCHAR},#{item.month,jdbcType=VARCHAR},#{item.procedureCode,jdbcType=VARCHAR}, #{item.materialCode,jdbcType=VARCHAR},#{item.dataSource,jdbcType=VARCHAR},#{item.monthPlanQty,jdbcType=NUMERIC}, #{item.lastMonthStock,jdbcType=NUMERIC},#{item.embryoBadQty,jdbcType=NUMERIC},#{item.monthPlanModifyQty,jdbcType=NUMERIC}, #{item.monthFinishQty,jdbcType=NUMERIC},#{item.monthRemainQty,jdbcType=NUMERIC},#{item.remark,jdbcType=VARCHAR}, #{item.delFlag,jdbcType=VARCHAR},#{item.createBy,jdbcType=VARCHAR},#{item.createTime,jdbcType=TIMESTAMP}, #{item.updateBy,jdbcType=VARCHAR},#{item.updateTime,jdbcType=TIMESTAMP} from dual
) x
